sys_script_include.script:
var EvenUtils = Class.create();
EvenUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getEventDetails: function() {
		var eventId = this.getParameter('sysparm_eventId'); 
        var gr = new GlideRecord('x_1790229_event_ma_event_record');
		gr.addQuery('sys_id', eventId);
		gr.query(); // Your event table name with scope prefix
        if (gr.next()) {
            return JSON.stringify({
                event_name: gr.getValue('u_event_name'),
                location: gr.getValue('u_location'),
                planner: gr.getDisplayValue('u_planner'),
                event_date: gr.getValue('u_event_date')
            });
        }
        return JSON.stringify({
            error: 'Event not found'
        });
    },

    type: 'EvenUtils'
});
